head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onaftercolumnfilterchange]<br/>DataList 모듈의 특정 Column 에 필터가 적용된 후에 발생합니다.",
    "validation" : [
        "DataList 모듈의 특정 Column 에 필터가 적용된 후에 발생합니다.",
        "setColumnFilter() 메소드로 필터가 적용된 후 onaftercolumnfilterchange 이벤트가 발생하며 필터가 해제될때는 발생하지 않습니다.",
        "onbeforecolumnfilterchange 이벤트가 발생한 후 onaftercolumnfilterchange 이벤트가 발생합니다.",
        "바인드 된 GridView 에 선택된 Row 가 필터 적용 후 인덱스가 변경되면 onbeforerowpositionchange, onrowpositionchange 이벤트가 onaftercolumnfilterchange 이벤트 전에 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩
    target1.bind("onbeforerowpositionchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforerowpositionchange=====");});
    target1.bind("onrowpositionchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowpositionchange=====");});
    target1.bind("onbeforecolumnfilterchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforecolumnfilterchange=====");});
    target1.bind("onaftercolumnfilterchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onaftercolumnfilterchange=====");});    

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;

    gridView1.setFocusedCell(1, 0, false);
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})       
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})
        isFilter = true;
    }	
};
